pochStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"hub","outputs":[{"internalType":"contract Hub","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"initialize","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"contextGraphId","type":"uint256"},{"internalType":"address","name":"publisher","type":"address"}],"name":"isAuthorizedPublisher","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"name","outputs":[{"internalType":"string","name":"","type":"string"}],"stateMutability":"pure","type":"function"},{"inputs":[],"name":"parametersStorage","outputs":[{"internalType":"contract ParametersStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"contextGraphId","type":"uint256"},{"internalType":"uint256","name":"kaId","type":"uint256"}],"name":"registerKnowledgeAsset","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"contextGraphId","type":"uint256"},{"internalType":"address","name":"agent","type":"address"}],"name":"removeParticipantAgent","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"bool","name":"_status","type":"bool"}],"name":"setStatus","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"status","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"contextGraphId","type":"uint256"}],"name":"sweepContextGraphEscrow","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"tokenContract","outputs":[{"internalType":"contract IERC20","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"contextGraphId","type":"uint256"},{"internalType":"address","name":"newAuthority","type":"address"},{"internalType":"uint256","name":"newAuthorityAccountId","type":"uint256"}],"name":"updatePublishAuthority","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"contextGraphId","type":"uint256"},{"internalType":"uint8","name":"publishPolicy","type":"uint8"},{"internalType":"address","name":"publishAuthority","type":"address"},{"internalType":"uint256","name":"publishAuthorityAccountId","type":"uint256"}],"name":"updatePublishPolicy","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"version","outputs":[{"internalType":"string","name":"","type":"string"}],"stateMutability":"pure","type":"function"}],"devdoc":{"details":"The legacy `addBatchToContextGraph` attestation / inclusion-proof      path is REMOVED (closes audit H2). Per-CG hosting committees and      per-CG quorum were removed in SPEC_CG_MEMORY_MODEL: every CG is      hosted by the sharding table at publish time, and the ACK quorum      is the system parameter `parametersStorage.minimumRequiredSignatures()`.      The only per-CG participant list is the EOA allow-list used for      curated / PCA flows.      Publish authorization supports the three curator types encoded in      ContextGraphStorage (see decision #22):        1. EOA    — publishAuthority = wallet, accountId = 0                    Read path: direct address match against stored authority.        2. Safe   — publishAuthority = multisig contract, accountId = 0                    (Safe executes txs as msg.sender, so address equality                    works transparently; ERC-1271 is not required here)        3. PCA    — accountId = DKGPublishingConvictionNFT account id;                    `publishAuthority` is a CREATE-TIME SNAPSHOT only.                    Read path LIVE-RESOLVES `ownerOf(accountId)` and                    accepts that owner or any registered agent of the                    same account. The stored snapshot is IGNORED at read                    time because it goes stale the moment the PCA NFT                    transfers. Governance mutators (participant-agent                    allow-list) similarly live-resolve via                    `_isOwnerOrAuthority`, and agents are NOT granted                    governance rights — only the NFT holder is.                    (Closes Codex HIGH: PCA auth drift on NFT transfer.)      The NFT reference is resolved from the Hub on every authorization      check so that a Phase 6 deployment made *after* the Phase 7 facade      starts working without a facade redeployment.      N17 note: KAV10's current callsite still passes the recovered node      signer wallet into `isAuthorizedPublisher`. That's a Phase 8 fix at      the caller — this facade is responsible for the logic being correct      when a correct principal is supplied.","errors":{"PCAAccountDoesNotExist(uint256)":[{"details":"Caller passed a non-zero PCA accountId but the NFT has no token minted      for that accountId (ownerOf reverted). The account does not exist."}],"PCAAuthorityMismatch(uint256,address,address)":[{"details":"Caller passed a PCA pair whose publishAuthority does NOT match the      actual owner of the NFT at accountId. Closes a silent-broadening      authorization vector: a mismatched pair would otherwise stack an      EOA direct-authority match AND a PCA-agent match on the same CG,      granting TWO distinct curators."}],"PCANotResolvable(uint256)":[{"details":"Caller passed a non-zero PCA accountId but the DKGPublishingConvictionNFT      is not currently resolvable via Hub (not deployed, not registered, or      Hub returned address(0)). Fail-closed: a caller that wants PCA mode      must deploy the NFT first, or use EOA/Safe mode instead."}],"ReentrancyGuardReentrantCall()":[{"details":"Unauthorized reentrant call."}]},"kind":"dev","methods":{"createContextGraph(address[],uint256,uint8,uint8,address,uint256,bytes32)":{"details":"Hosts and ACK quorum are network-level concerns: the sharding table      supplies hosts at publish time and `parametersStorage.minimumRequiredSignatures()`      sets the quorum. CGs do not declare a per-CG hosting committee.","params":{"accessPolicy":"0 = public/discoverable, 1 = private/curated","metadataBatchId":"Batch ID describing the CG metadata (0 if none)","nameHash":"OT-RFC-38 / LU-6 Phase B — opt-in stable wire                                  identifier the curator commits to (intended to be                                  `keccak256(bytes(cleartextId))` so hosting cores                                  can auto-subscribe to the SWM gossip topic on                                  receipt of `ContextGraphCreated`). Pass                                  `bytes32(0)` to opt out (host-mode discovery for                                  that CG then runs through the beacon path only).","participantAgents":"EOA allow-list (no zeros, no dups)","publishAuthority":"Curator address (required when curated; ignored when open)","publishAuthorityAccountId":"Non-zero -> PCA curator type. Requires curated. Ignored when open.","publishPolicy":"0 = curated, 1 = open"},"returns":{"contextGraphId":"          Newly assigned context graph ID (= ERC-721 token ID)"}},"isAuthorizedPublisher(uint256,address)":{"details":"Implements the 3-curator-type model per decision #22:      - Open CGs (publishPolicy == 1) allow any non-zero principal.      - Curated + EOA curator (accountId == 0): direct address equality        against the STORED `publishAuthority`. The storage layer auto-        rotates this field when the CG NFT transfers, so it is always        live for EOA/Safe mode.      - Curated + Safe multisig (accountId == 0): same direct address        equality. A Gnosis Safe IS `msg.sender` when it executes a        transaction, so any call made on behalf of the Safe arrives        here with `publisher == safeAddress`. No ERC-1271 signature        check is required at this layer.      - Curated + PCA (accountId != 0): the stored `publishAuthority`        is a CREATE-TIME SNAPSHOT that goes STALE the moment the PCA        NFT transfers. The stored snapshot is therefore IGNORED for        authorization. Instead we LIVE-RESOLVE the current PCA NFT        owner via `IDKGPublishingConvictionNFT.ownerOf(accountId)` and        accept either (a) that live owner directly or (b) a registered        agent whose `agentToAccountId(publisher) == accountId`. Both        mappings on the NFT contract are cleared by the transfer hook,        so stale agent entries automatically stop authorizing.      Branch order is IMPORTANT. Because the EOA/Safe branch matches on      the stored authority snapshot, it MUST NOT run in PCA mode — an      unconditional direct-equality check before the accountId branch      would silently authorize a stale ex-owner. (Closes Codex HIGH      "PCA auth drift on NFT transfer": Alice creates a CG in PCA mode,      transfers the NFT to Bob, and the stored authority still reads      Alice. The pre-fix code returned true for Alice; the fix ignores      the snapshot in PCA mode and live-resolves ownerOf(accountId)      which now returns Bob.)      The DKGPublishingConvictionNFT reference is resolved on every call      via a `try/catch` on `hub.getContractAddress("DKGPublishingConvictionNFT")`.      Hub's `getContractAddress` reverts with `ContractDoesNotExist` when      the contract is not registered (see UnorderedNamedContractDynamicSet.get),      so the catch branch handles gracefully-degraded environments where      Phase 6 has not been deployed yet. Using a fresh lookup each call      (rather than caching on `initialize()`) lets the PCA branch start      working without a facade redeployment once Phase 6 lands. Any      resolution failure in PCA mode yields `false` (fail-closed read      path — unlike the write path, which reverts).      View-only — no state mutations.      N17 note: the external signature intentionally takes the paying      principal as `publisher` rather than the recovered publisher-node      signer. The matching caller-side fix lives in `KnowledgeAssetsV10`      Phase 8 — `_executePublishCore` and `_executeUpdateCore` both pass      `msg.sender` here instead of the recovered node wallet."},"registerKnowledgeAsset(uint256,uint256)":{"details":"Thin wrapper over `ContextGraphStorage.registerKnowledgeAssetToContextGraph`.      Exists so Phase 8's `KnowledgeAssetsV10.publish` / `publishDirect`      can call the facade (stable interface) instead of reaching into      storage directly. `onlyContracts`-gated at the facade layer so the      entry point has one canonical caller — the KA contract — and no      direct EOA call path."}},"title":"ContextGraphs","version":1},"userdoc":{"events":{"ContextGraphEscrowSwept(uint256,uint96)":{"notice":"Emitted when an admin sweeps a CG's residual escrow to the pool."},"ContextGraphRegistrationDeposited(uint256,address,uint96)":{"notice":"Emitted when a CG registration deposit is pulled at creation."}},"kind":"user","methods":{"createContextGraph(address[],uint256,uint8,uint8,address,uint256,bytes32)":{"notice":"Create a new context graph. Mints an ERC-721 to msg.sender."},"isAuthorizedPublisher(uint256,address)":{"notice":"Check whether `publisher` is authorized to publish to a context graph."},"registerKnowledgeAsset(uint256,uint256)":{"notice":"Bind a Knowledge Asset to a Context Graph via the facade."},"sweepContextGraphEscrow(uint256)":{"notice":"Admin: RETIRE a CG and reclaim its residual registration escrow         into the staker reward pool (current epoch). For abandoned / spam         CGs whose deposit was never spent on publishing. Deactivation is         ATOMIC with the sweep, so this can never silently drain an ACTIVE         CG owner's prepaid publishing budget while leaving the CG live —         sweeping a CG is retiring it. The TRAC is already in the CSS vault,         so this only deactivates, credits the epoch pool, and clears the         per-CG accounting. Never refunds to the depositor."}},"notice":"Stateless logic facade for Context Graph operations. All state lives in         ContextGraphStorage (ERC-721 registry). This contract is replaceable via Hub.","version":1}},"settings":{"compilationTarget":{"contracts/ContextGraphs.sol":"ContextGraphs"},"evmVersion":"london","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":200},"remappings":[],"viaIR":true},"sources":{"@openzeppelin/contracts/access/Ownable.sol":{"content":"// SPDX-License-Identifier: MIT
